import { mediaUrl } from './api.js';
import { contentAssets, resolveContentAsset } from './content-assets.js';
export const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
export const money = value => `${Number(value || 0).toLocaleString('ru-RU')} сом`;
export const date = value => value ? new Intl.DateTimeFormat('ru-RU', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Bishkek' }).format(new Date(value)) : '—';
export const shortId = id => id ? String(id).slice(0, 8).toUpperCase() : '—';
export const statuses = { SEARCHING: 'Поиск водителя', ASSIGNED: 'Водитель назначен', ARRIVED: 'Водитель приехал', IN_PROGRESS: 'В пути', COMPLETED: 'Завершён', CANCELLED: 'Отменён', NO_DRIVER: 'Нет водителя', PLACED: 'Новый', CONFIRMED: 'Подтверждён', PREPARING: 'Готовится', READY: 'Готов к выдаче', DELIVERING: 'Доставляется', NOT_STARTED: 'Не начата', DRAFT: 'Черновик', SUBMITTED: 'Новая заявка', UNDER_REVIEW: 'На проверке', CORRECTION_REQUIRED: 'Нужны исправления', APPROVED: 'Одобрена', REJECTED: 'Отклонена', BLOCKED: 'Заблокирована', NOT_UPLOADED: 'Не загружен', UPLOADED: 'Загружен', ACTIVE: 'Действует', EXPIRING: 'Скоро истекает', EXPIRED: 'Истёк' };
export const badge = status => `<span class="badge status-${esc(status)}">${esc(statuses[status] || status)}</span>`;
const icons = { grid: '<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>', orders: '<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>', drivers: '<path d="m4 10 2-6h12l2 6M3 10h18v8H3zM6 18v3m12-3v3M6 14h2m8 0h2"/>', tariffs: '<path d="M4 7h16M4 17h16M8 4v6m8 4v6"/>', food: '<path d="M4 3v7h6V3M7 3v18m11-18c-4 4-4 10 0 10V3Zm0 10v8"/>', banner: '<rect x="3" y="4" width="18" height="16" rx="2"/><circle cx="8" cy="9" r="1.5"/><path d="m3 17 6-5 4 3 3-3 5 5"/>', audit: '<path d="M12 8v5l3 2M3 5v5h5"/><path d="M3.4 10a9 9 0 1 1 1 7"/>', plus: '<path d="M12 5v14M5 12h14"/>', arrow: '<path d="m9 5 7 7-7 7"/>', back: '<path d="m15 5-7 7 7 7"/>', refresh: '<path d="M20 4v6h-6M4 20v-6h6M5 8a8 8 0 0 1 13-3l2 5M4 14l2 5a8 8 0 0 0 13-3"/>', search: '<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>', close: '<path d="m6 6 12 12M6 18 18 6"/>', logout: '<path d="M10 4H4v16h6m4-4 4-4-4-4m-5 4h12"/>', upload: '<path d="M12 16V3m-5 5 5-5 5 5M4 15v6h16v-6"/>', check: '<path d="m5 12 4 4L19 6"/>', lock: '<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/>', menu: '<path d="M4 6h16M4 12h16M4 18h16"/>', clock: '<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>', edit: '<path d="m14 4 6 6M4 20l4-1L21 6l-4-4L4 15Z"/>', trash: '<path d="M3 6h18M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7"/>' };
export const icon = (name, size = 20) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name] || icons.orders}</svg>`;
export const button = (label, action, extras = '', style = 'secondary') => `<button type="button" class="button ${style}" data-action="${action}" ${extras}>${label}</button>`;
export const field = (label, name, value = '', options = {}) => `<label class="field ${options.wide ? 'wide' : ''}"><span>${esc(label)}${options.required ? ' *' : ''}</span><input name="${esc(name)}" value="${esc(value)}" type="${options.type || 'text'}" ${options.required ? 'required' : ''} ${options.min !== undefined ? `min="${options.min}"` : ''} ${options.max !== undefined ? `max="${options.max}"` : ''} ${options.step ? `step="${options.step}"` : ''} ${options.maxLength ? `maxlength="${options.maxLength}"` : ''} ${options.disabled ? 'disabled' : ''} ${options.placeholder ? `placeholder="${esc(options.placeholder)}"` : ''}/>${options.hint ? `<small>${esc(options.hint)}</small>` : ''}</label>`;
export const area = (label, name, value = '', wide = true, maxLength = 1000) => `<label class="field ${wide ? 'wide' : ''}"><span>${esc(label)}</span><textarea name="${esc(name)}" rows="3" maxlength="${maxLength}">${esc(value)}</textarea></label>`;
export const toggle = (label, name, checked, hint = '') => `<label class="toggle"><input type="checkbox" name="${name}" ${checked ? 'checked' : ''}><span class="switch"></span><span>${esc(label)}${hint ? `<small>${esc(hint)}</small>` : ''}</span></label>`;
export const select = (label, name, values, value) => `<label class="field"><span>${esc(label)}</span><select name="${name}">${values.map(([id, text]) => `<option value="${esc(id)}" ${String(value) === String(id) ? 'selected' : ''}>${esc(text)}</option>`).join('')}</select></label>`;
export const empty = (title = 'Пока ничего нет', subtitle = 'Новые данные появятся здесь автоматически.', name = 'orders') => `<div class="empty">${icon(name, 32)}<h3>${esc(title)}</h3><p>${esc(subtitle)}</p></div>`;
export const loading = () => '<div class="loading" role="status"><span class="spinner"></span>Загружаем данные…</div>';
export const errorBox = message => `<div class="error-box" role="alert"><span>${esc(message)}</span>${button('Повторить', 'reload')}</div>`;
export function photo(url, key, alt = '', className = '', fallbackKey = '') {
  const remote = mediaUrl(url), asset = resolveContentAsset(key, fallbackKey), src = remote || asset?.src;
  if (!src) return `<span class="photo-empty ${esc(className)}" role="img" aria-label="${esc(alt ? 'Фото отсутствует: ' + alt : 'Фото отсутствует')}">${icon('banner', 28)}</span>`;
  if (!remote && asset.crop) {
    const [x, y, width, height] = asset.crop;
    return `<svg class="photo-crop ${esc(className)}" xmlns="http://www.w3.org/2000/svg" viewBox="${x} ${y} ${width} ${height}" preserveAspectRatio="xMidYMid ${asset.fit === 'contain' ? 'meet' : 'slice'}" role="img" aria-label="${esc(alt)}"><image href="${esc(src)}" width="${asset.width}" height="${asset.height}"/></svg>`;
  }
  const fit = !remote && asset.fit === 'contain' ? ' style="object-fit:contain"' : '';
  return `<img class="${esc(className)}" src="${esc(src)}" alt="${esc(alt)}" loading="lazy" referrerpolicy="no-referrer"${fit}>`;
}

const contentImageNames = { 'sushi-roll': 'Суши — ресторан', kfc: 'Курица — ресторан', halva: 'Восточная кухня — ресторан', 'ali-burger': 'Бургеры — ресторан', philadelphia: 'Филадельфия', california: 'Калифорния', tempura: 'Темпура', salmon: 'Ролл с лососем', 'salmon-nigiri': 'Нигири с лососем', 'shrimp-nigiri': 'Нигири с креветкой', 'sushi-set': 'Суши — сет', 'chicken-burger': 'Бургер с курицей', 'chicken-bucket': 'Баскет с курицей', 'chicken-wings': 'Куриные крылья', 'chicken-strips': 'Стрипсы', 'chicken-wrap': 'Ролл с курицей', fries: 'Картофель фри', coleslaw: 'Коул слоу', burger: 'Бургер', 'burger-combo': 'Бургер комбо', 'onion-rings': 'Луковые кольца', 'double-cheeseburger': 'Двойной чизбургер', 'bbq-burger': 'Бургер барбекю', 'mushroom-burger': 'Бургер с грибами', 'caesar-salad': 'Салат Цезарь', 'chicken-combo': 'Курица комбо', lemonade: 'Лимонад', tea: 'Чай', cola: 'Кола', plov: 'Плов', samsa: 'Самса', manti: 'Манты', lagman: 'Лагман', beshbarmak: 'Бешбармак', shorpo: 'Шорпо', kuurdak: 'Куурдак', oromo: 'Оромо', achichuk: 'Ачичук', flatbread: 'Лепёшка', baursak: 'Боорсоки', edamame: 'Эдамаме', 'chicken-nuggets': 'Наггетсы', 'potato-wedges': 'Картофель по-деревенски', 'veggie-burger': 'Овощной бургер', 'dragon-roll': 'Ролл Дракон', 'baked-salmon-roll': 'Запечённый ролл', 'shrimp-tempura': 'Креветки темпура', 'miso-soup': 'Мисо суп', soy: 'Соевый соус', ginger: 'Имбирь', wasabi: 'Васаби', 'nearby-promo': 'Рестораны рядом — баннер', 'homepage-burger': 'Бургер — главный экран' };
export const contentImageChoices = () => Object.entries(contentImageNames).filter(([key]) => contentAssets[key]).map(([key, label]) => [key, label]);
const campaignColors = { 'sushi-roll': '#174C39', kfc: '#981B17', halva: '#315344', 'ali-burger': '#AF4715' };
export function bannerPreview(item, restaurants = [], square = true) {
  const restaurant = restaurants.find(restaurant => restaurant.id === item.restaurantId), restaurantName = restaurant?.catalog?.name || restaurant?.name || '';
  const designed = item.actionType === 'RESTAURANT' && !item.imageUrl && contentAssets[item.imageKey]?.kind === 'photograph';
  const color = campaignColors[item.restaurantId] || '#174C39';
  const image = item.imageUrl || item.imageKey ? photo(item.imageUrl, item.imageKey, item.title || 'Баннер') : '';
  return `<div class="banner-preview ${square ? 'square' : 'landscape'} ${designed ? 'campaign-preview' : image ? 'creative-preview' : 'text-preview'}" ${designed ? `style="--campaign-color:${color}"` : ''}>${image}${designed ? `<div class="campaign-gradient"></div><div class="campaign-copy"><h3>${esc(item.title)}</h3><span class="campaign-label">${esc(item.subtitle || restaurantName)}</span>${restaurantName ? `<span class="campaign-brand">${esc(restaurantName)}</span>` : ''}</div>` : !image ? `<div class="banner-copy"><h3>${esc(item.title)}</h3><p>${esc(item.subtitle)}</p></div>` : ''}</div>`;
}
export function pager(data, busy = false) { const page = data?.page || 1, size = data?.pageSize || 25, total = data?.total || 0; return `<div class="pager"><span>${total ? `${(page - 1) * size + 1}–${Math.min(page * size, total)} из ${total}` : '0 записей'}</span><div>${button(icon('back'), 'page-prev', `aria-label="Предыдущая страница" ${busy || page <= 1 ? 'disabled' : ''}`)}<span>${page}</span>${button(icon('arrow'), 'page-next', `aria-label="Следующая страница" ${busy || page * size >= total ? 'disabled' : ''}`)}</div></div>`; }
